input.query:
WITH c AS (
  SELECT claim_id FROM claim WHERE peril='OWN_DAMAGE' AND EXTRACT(year FROM accident_date)=2024 AND report_date<=DATE '2025-12-31'
),
loss AS (
  SELECT SUM(t.amount) AS reported_loss FROM claim_txn t JOIN c USING(claim_id)
  WHERE t.cost_type='INDEMNITY' AND t.txn_date<=DATE '2025-12-31'
),
cnt AS (SELECT COUNT(*) n FROM c)
SELECT reported_loss, n AS reported_claims, reported_loss/n AS severity_reported FROM loss, cnt;
